    size_t negative = 0;
    memset(counts, 0, nbins * sizeof *counts);
    for (size_t i = 0; i < n; i++) {
        if (samples[i] < 0) {
            negative++;
            continue;
        }
        size_t bin = (size_t)(samples[i] / bin_width_ns);
        counts[bin < nbins ? bin : nbins - 1]++;
    }
    return negative;
}

