/* A sensor event as it flows through the pipeline into storage. */
#ifndef EVENT_H
#define EVENT_H

#include <stdint.h>
#include <time.h>

typedef enum { EV_MOTION_START, EV_MOTION_END, EV_DISTANCE } event_kind;

typedef struct {
    uint64_t        t_mono_ns;   /* CLOCK_MONOTONIC time of the underlying edge */
    struct timespec t_wall;      /* CLOCK_REALTIME when the event was handled */
    const char     *mode;        /* "irq" or "poll" */
    event_kind      kind;
    double          distance_cm; /* EV_DISTANCE only */
    int             echo_ok;     /* EV_DISTANCE only: 1 if reading in range */
    int64_t         latency_ns;  /* handled - edge time; negative if unknown */
} event_record;

#endif

/* HC-SR04 echo timing logic, independent of how edges are observed.
 * The same tracker consumes kernel-timestamped edges (irq) or transitions
 * found by sampling (poll). */
#ifndef HCSR04_H
#define HCSR04_H

#include "gpio_backend.h"

#include <stdbool.h>
#include <stdint.h>

#define HCSR04_TIMEOUT_NS      30000000ULL /* > 400 cm round trip (~23.3 ms) */
#define HCSR04_MIN_CM          2.0
#define HCSR04_MAX_CM          400.0
#define HCSR04_SOUND_CM_PER_NS 3.43e-5     /* 343 m/s, air at ~20 °C */

typedef enum { HCSR04_OK, HCSR04_OUT_OF_RANGE, HCSR04_TIMEOUT } hcsr04_status;

typedef struct {
    hcsr04_status status;
    double        cm;       /* valid unless TIMEOUT */
    uint64_t      width_ns; /* echo pulse width; 0 on TIMEOUT */
    uint64_t      rise_ns;  /* echo rising edge; 0 if it never rose */
} hcsr04_reading;

typedef enum { HCSR04_IDLE, HCSR04_WAIT_RISE, HCSR04_WAIT_FALL } hcsr04_phase;

typedef struct {
    hcsr04_phase phase;
    uint64_t     trig_ns;
    uint64_t     rise_ns;
} hcsr04_tracker;

double hcsr04_width_to_cm(uint64_t width_ns);

void hcsr04_init(hcsr04_tracker *t);

/* Call right after the 10 µs TRIG pulse; arms the tracker for one echo. */
void hcsr04_start(hcsr04_tracker *t, uint64_t trig_ns);

/* Feed one ECHO edge. Returns true and fills *out when a measurement completes.
 * Edges arriving while idle (stray echoes) are ignored. */
bool hcsr04_on_edge(hcsr04_tracker *t, gpio_edge_type type, uint64_t ts_ns,
                    hcsr04_reading *out);

/* Returns true and fills *out with a TIMEOUT reading if the armed measurement
 * has waited longer than HCSR04_TIMEOUT_NS for its next edge. */
bool hcsr04_check_timeout(hcsr04_tracker *t, uint64_t now_ns, hcsr04_reading *out);

#endif

#include "hcsr04.h"

double hcsr04_width_to_cm(uint64_t width_ns)
{
    /* Sound travels to the object and back, so halve the round trip. */
    return (double)width_ns * HCSR04_SOUND_CM_PER_NS / 2.0;
}

void hcsr04_init(hcsr04_tracker *t)
{
    *t = (hcsr04_tracker){.phase = HCSR04_IDLE};
}

void hcsr04_start(hcsr04_tracker *t, uint64_t trig_ns)
{
    *t = (hcsr04_tracker){.phase = HCSR04_WAIT_RISE, .trig_ns = trig_ns};
}

bool hcsr04_on_edge(hcsr04_tracker *t, gpio_edge_type type, uint64_t ts_ns,
                    hcsr04_reading *out)
{
    switch (t->phase) {
    case HCSR04_IDLE:
        return false;
    case HCSR04_WAIT_RISE:
        if (type == GPIO_EDGE_RISING) {
            t->rise_ns = ts_ns;
            t->phase = HCSR04_WAIT_FALL;
        }
        return false;
    case HCSR04_WAIT_FALL:
        if (type == GPIO_EDGE_RISING) {
            /* Missed the falling edge; restart from this rise. */
            t->rise_ns = ts_ns;
            return false;
        }
        break;
    }

    uint64_t width = ts_ns >= t->rise_ns ? ts_ns - t->rise_ns : 0;
    double cm = hcsr04_width_to_cm(width);
    *out = (hcsr04_reading){
        .status = (cm < HCSR04_MIN_CM || cm > HCSR04_MAX_CM) ? HCSR04_OUT_OF_RANGE
                                                             : HCSR04_OK,
        .cm = cm,
        .width_ns = width,
        .rise_ns = t->rise_ns,
    };
    t->phase = HCSR04_IDLE;
    return true;
}

bool hcsr04_check_timeout(hcsr04_tracker *t, uint64_t now_ns, hcsr04_reading *out)
{
    uint64_t since;
    switch (t->phase) {
    case HCSR04_WAIT_RISE:
        since = t->trig_ns;
        break;
    case HCSR04_WAIT_FALL:
        since = t->rise_ns;
        break;
    default:
        return false;
    }
    if (now_ns <= since || now_ns - since <= HCSR04_TIMEOUT_NS)
        return false;

    *out = (hcsr04_reading){
        .status = HCSR04_TIMEOUT,
        .rise_ns = t->phase == HCSR04_WAIT_FALL ? t->rise_ns : 0,
    };
    t->phase = HCSR04_IDLE;
    return true;
}

/* PIR motion state machine with an optional stability debounce.
 * A level change is committed only after it holds for debounce_ns; the event
 * keeps the timestamp of the original edge so latency measurements are not
 * inflated by the debounce window. */
#ifndef PIR_H
#define PIR_H

#include <stdbool.h>
#include <stdint.h>

typedef enum { PIR_NONE, PIR_MOTION_START, PIR_MOTION_END } pir_event;

typedef struct {
    uint64_t debounce_ns;
    int      level;         /* committed level: 1 = motion */
    bool     pending;
    int      pending_level;
    uint64_t pending_ns;    /* edge time of the pending change */
} pir_state;

void pir_init(pir_state *s, uint64_t debounce_ns, int initial_level);

/* Report the line level observed at ts_ns (from an edge or a poll sample).
 * Returns a committed event, with its edge time in *event_ns. */
pir_event pir_on_level(pir_state *s, int level, uint64_t ts_ns, uint64_t *event_ns);

/* Commit a pending change that has been stable for debounce_ns by now_ns. */
pir_event pir_tick(pir_state *s, uint64_t now_ns, uint64_t *event_ns);

/* If a change is pending, stores when pir_tick should next run and returns true. */
bool pir_deadline(const pir_state *s, uint64_t *deadline_ns);

#endif

#include "pir.h"

static pir_event commit(pir_state *s, int level)
{
    s->level = level;
    s->pending = false;
    return level ? PIR_MOTION_START : PIR_MOTION_END;
}

void pir_init(pir_state *s, uint64_t debounce_ns, int initial_level)
{
    *s = (pir_state){.debounce_ns = debounce_ns, .level = initial_level ? 1 : 0};
}

pir_event pir_tick(pir_state *s, uint64_t now_ns, uint64_t *event_ns)
{
    if (!s->pending || now_ns < s->pending_ns || now_ns - s->pending_ns < s->debounce_ns)
        return PIR_NONE;
    *event_ns = s->pending_ns;
    return commit(s, s->pending_level);
}

pir_event pir_on_level(pir_state *s, int level, uint64_t ts_ns, uint64_t *event_ns)
{
    level = level ? 1 : 0;

    /* A pending change that already outlasted the debounce window is real,
     * even if the line moves again now. With debounce > 0 the new level can
     * only become pending below, so at most one event is returned. */
    pir_event ev = pir_tick(s, ts_ns, event_ns);

    if (s->pending) {
        if (level == s->level)
            s->pending = false; /* glitch: returned before it was stable */
        return ev;
    }
    if (level == s->level)
        return ev;
    if (s->debounce_ns == 0) {
        *event_ns = ts_ns;
        return commit(s, level);
    }
    s->pending = true;
    s->pending_level = level;
    s->pending_ns = ts_ns;
    return ev;
}

bool pir_deadline(const pir_state *s, uint64_t *deadline_ns)
{
    if (!s->pending)
        return false;
    *deadline_ns = s->pending_ns + s->debounce_ns;
    return true;
}

/* CSV formatting for event records (RFC 4180 quoting). File I/O lives in csv_store. */
#ifndef CSV_H
#define CSV_H

#include "event.h"

#include <stddef.h>
#include <time.h>

#define CSV_HEADER "t_mono_ns,t_wall_iso,mode,event,distance_cm,echo_ok,latency_ns\n"

/* Each function writes a NUL-terminated string into dst and returns its length,
 * or -1 if it does not fit in n bytes. */

/* Quotes the field if it contains a comma, quote, CR or LF; doubles inner quotes. */
int csv_escape_field(char *dst, size_t n, const char *src);

/* UTC ISO-8601 with microseconds, e.g. 2026-10-28T17:26:28.123456Z */
int csv_format_wall_time(char *dst, size_t n, struct timespec ts);

const char *csv_event_name(event_kind kind);

/* One CSV row including the trailing newline. Distance and echo_ok are empty
 * for motion events; latency is empty when negative (unknown). */
int csv_format_record(char *dst, size_t n, const event_record *r);

#endif

#include "csv.h"

#include <inttypes.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>

int csv_escape_field(char *dst, size_t n, const char *src)
{
    bool quote = strpbrk(src, ",\"\r\n") != NULL;
    size_t len = 0;

#define PUT(c)            \
    do {                  \
        if (len + 1 >= n) \
            return -1;    \
        dst[len++] = (c); \
    } while (0)

    if (quote)
        PUT('"');
    for (const char *p = src; *p; p++) {
        if (*p == '"')
            PUT('"');
        PUT(*p);
    }
    if (quote)
        PUT('"');
#undef PUT

    if (n == 0)
        return -1;
    dst[len] = '\0';
    return (int)len;
}

int csv_format_wall_time(char *dst, size_t n, struct timespec ts)
{
    struct tm tm;
    if (!gmtime_r(&ts.tv_sec, &tm))
        return -1;
    char date[32];
    if (strftime(date, sizeof date, "%Y-%m-%dT%H:%M:%S", &tm) == 0)
        return -1;
    int len = snprintf(dst, n, "%s.%06ldZ", date, ts.tv_nsec / 1000);
    return (len < 0 || (size_t)len >= n) ? -1 : len;
}

const char *csv_event_name(event_kind kind)
{
    switch (kind) {
    case EV_MOTION_START:
        return "motion_start";
    case EV_MOTION_END:
        return "motion_end";
    case EV_DISTANCE:
        return "distance";
    }
    return "unknown";
}

int csv_format_record(char *dst, size_t n, const event_record *r)
{
    char wall[40], mode[64], dist[32] = "", echo[4] = "", lat[24] = "";

    if (csv_format_wall_time(wall, sizeof wall, r->t_wall) < 0 ||
        csv_escape_field(mode, sizeof mode, r->mode ? r->mode : "") < 0)
        return -1;
    if (r->kind == EV_DISTANCE) {
        snprintf(dist, sizeof dist, "%.2f", r->distance_cm);
        snprintf(echo, sizeof echo, "%d", r->echo_ok ? 1 : 0);
    }
    if (r->latency_ns >= 0)
        snprintf(lat, sizeof lat, "%" PRId64, r->latency_ns);

    int len = snprintf(dst, n, "%" PRIu64 ",%s,%s,%s,%s,%s,%s\n", r->t_mono_ns, wall, mode,
                       csv_event_name(r->kind), dist, echo, lat);
    return (len < 0 || (size_t)len >= n) ? -1 : len;
}

/* Latency distribution statistics for the interrupt vs. polling comparison. */
#ifndef METRICS_H
#define METRICS_H

#include <stddef.h>
#include <stdint.h>

typedef struct {
    size_t  n;
    int64_t min, p50, p90, p99, max;
    double  mean;
} latency_summary;

/* Nearest-rank percentile (pct 0..100) of an ascending-sorted array, n > 0. */
int64_t latency_percentile_sorted(const int64_t *sorted, size_t n, unsigned pct);

/* Summarizes samples without modifying them. Returns 0, or -1 if n == 0 or
 * allocation fails. */
int latency_summarize(const int64_t *samples, size_t n, latency_summary *out);

/* Fixed-width histogram: counts[i] holds samples in [i*w, (i+1)*w) and the last
 * bin also holds everything above. counts must have nbins >= 1 entries and
 * bin_width_ns must be > 0. Negative samples are not counted; returns how many
 * there were. */
size_t latency_histogram(const int64_t *samples, size_t n, int64_t bin_width_ns,
                         uint64_t *counts, size_t nbins);

#endif

#include "metrics.h"

#include <stdlib.h>
#include <string.h>

static int cmp_i64(const void *a, const void *b)
{
    int64_t x = *(const int64_t *)a, y = *(const int64_t *)b;
    return (x > y) - (x < y);
}

int64_t latency_percentile_sorted(const int64_t *sorted, size_t n, unsigned pct)
{
    if (pct > 100)
        pct = 100;
    size_t rank = ((size_t)pct * n + 99) / 100; /* ceil(pct/100 * n) */
    if (rank < 1)
        rank = 1;
    return sorted[rank - 1];
}

int latency_summarize(const int64_t *samples, size_t n, latency_summary *out)
{
    if (n == 0)
        return -1;
    int64_t *sorted = malloc(n * sizeof *sorted);
    if (!sorted)
        return -1;
    memcpy(sorted, samples, n * sizeof *sorted);
    qsort(sorted, n, sizeof *sorted, cmp_i64);

    double sum = 0;
    for (size_t i = 0; i < n; i++)
        sum += (double)sorted[i];

    *out = (latency_summary){
        .n = n,
        .min = sorted[0],
        .p50 = latency_percentile_sorted(sorted, n, 50),
        .p90 = latency_percentile_sorted(sorted, n, 90),
        .p99 = latency_percentile_sorted(sorted, n, 99),
        .max = sorted[n - 1],
        .mean = sum / (double)n,
    };
    free(sorted);
    return 0;
}

size_t latency_histogram(const int64_t *samples, size_t n, int64_t bin_width_ns,
                         uint64_t *counts, size_t nbins)
{
    size_t negative = 0;
    memset(counts, 0, nbins * sizeof *counts);
    for (size_t i = 0; i < n; i++) {
        if (samples[i] < 0) {
            negative++;
            continue;
        }
        size_t bin = (size_t)(samples[i] / bin_width_ns);
        counts[bin < nbins ? bin : nbins - 1]++;
    }
    return negative;
}

