/* Test-only controls for the mock GPIO backend (gpio_mock_open in gpio_backend.h). */
#ifndef GPIO_MOCK_H
#define GPIO_MOCK_H

#include "gpio_backend.h"

#include <stddef.h>

/* Queue an edge. wait_edge returns queued edges in FIFO order and applies each
 * one to the line level as it is delivered. Returns 0, or -1 on bad pin / OOM. */
int gpio_mock_push_edge(gpio_backend *b, unsigned int pin, gpio_edge_type type,
                        uint64_t timestamp_ns);

/* Set a line level directly, as a polled read would see it. */
int gpio_mock_set_level(gpio_backend *b, unsigned int pin, int level);

/* Number of queued edges not yet delivered. */
size_t gpio_mock_pending(const gpio_backend *b);

/* Number of writes made to a pin (e.g. TRIG pulses). */
unsigned gpio_mock_write_count(const gpio_backend *b, unsigned int pin);

#endif

/* Mock GPIO backend: line levels in memory plus a FIFO of scripted edges with
 * injected timestamps. No hardware access. */
#include "gpio_mock.h"

#include <stdlib.h>

#define MOCK_MAX_PIN 64

typedef struct {
    int        level[MOCK_MAX_PIN];
    unsigned   writes[MOCK_MAX_PIN];
    gpio_edge *edges;
    size_t     head, count, cap;
} mock_state;

static int mock_read(gpio_backend *b, unsigned int pin)
{
    mock_state *s = b->impl;
    return pin < MOCK_MAX_PIN ? s->level[pin] : -1;
}

static int mock_write(gpio_backend *b, unsigned int pin, int value)
{
    mock_state *s = b->impl;
    if (pin >= MOCK_MAX_PIN)
        return -1;
    s->level[pin] = value ? 1 : 0;
    s->writes[pin]++;
    return 0;
}

static int mock_wait_edge(gpio_backend *b, int64_t timeout_ns, gpio_edge *out)
{
    (void)timeout_ns; /* scripted time: an empty queue is an immediate timeout */
    mock_state *s = b->impl;
    if (s->head == s->count)
        return 0;
    *out = s->edges[s->head++];
    s->level[out->pin] = out->type == GPIO_EDGE_RISING;
    return 1;
}

static void mock_close(gpio_backend *b)
{
    mock_state *s = b->impl;
    free(s->edges);
    free(s);
    free(b);
}

int gpio_mock_push_edge(gpio_backend *b, unsigned int pin, gpio_edge_type type,
                        uint64_t timestamp_ns)
{
    mock_state *s = b->impl;
    if (pin >= MOCK_MAX_PIN)
        return -1;
    if (s->count == s->cap) {
        size_t cap = s->cap ? s->cap * 2 : 16;
        gpio_edge *e = realloc(s->edges, cap * sizeof *e);
        if (!e)
            return -1;
        s->edges = e;
        s->cap = cap;
    }
    s->edges[s->count++] = (gpio_edge){.pin = pin, .type = type, .timestamp_ns = timestamp_ns};
    return 0;
}

int gpio_mock_set_level(gpio_backend *b, unsigned int pin, int level)
{
    mock_state *s = b->impl;
    if (pin >= MOCK_MAX_PIN)
        return -1;
    s->level[pin] = level ? 1 : 0;
    return 0;
}

size_t gpio_mock_pending(const gpio_backend *b)
{
    const mock_state *s = b->impl;
    return s->count - s->head;
}

unsigned gpio_mock_write_count(const gpio_backend *b, unsigned int pin)
{
    const mock_state *s = b->impl;
    return pin < MOCK_MAX_PIN ? s->writes[pin] : 0;
}

gpio_backend *gpio_mock_open(void)
{
    gpio_backend *b = calloc(1, sizeof *b);
    mock_state *s = calloc(1, sizeof *s);
    if (!b || !s) {
        free(b);
        free(s);
        return NULL;
    }
    *b = (gpio_backend){
        .name = "mock",
        .read = mock_read,
        .write = mock_write,
        .wait_edge = mock_wait_edge,
        .close = mock_close,
        .impl = s,
    };
    return b;
}

/* Software-only: HC-SR04 echo-width conversion, range checks, and timeouts. */
#include "../test_util.h"
#include "hcsr04.h"

#define US 1000ULL
#define MS 1000000ULL

static void test_conversion(void)
{
    CHECK_NEAR(hcsr04_width_to_cm(0), 0.0, 1e-9);
    CHECK_NEAR(hcsr04_width_to_cm(1 * MS), 17.15, 1e-6);
    CHECK_NEAR(hcsr04_width_to_cm(5831 * US), 100.0, 0.01);
}

static void test_valid_echo(void)
{
    hcsr04_tracker t;
    hcsr04_reading r;
    hcsr04_init(&t);
    hcsr04_start(&t, 0);
    CHECK(!hcsr04_on_edge(&t, GPIO_EDGE_FALLING, 100 * US, &r)); /* ignored before rise */
    CHECK(!hcsr04_on_edge(&t, GPIO_EDGE_RISING, 500 * US, &r));
    CHECK(hcsr04_on_edge(&t, GPIO_EDGE_FALLING, 1500 * US, &r));
    CHECK(r.status == HCSR04_OK);
    CHECK(r.width_ns == 1 * MS);
    CHECK(r.rise_ns == 500 * US);
    CHECK_NEAR(r.cm, 17.15, 1e-6);
    CHECK(t.phase == HCSR04_IDLE);
}

static void test_stray_edges_ignored_when_idle(void)
{
    hcsr04_tracker t;
    hcsr04_reading r;
    hcsr04_init(&t);
    CHECK(!hcsr04_on_edge(&t, GPIO_EDGE_RISING, 1, &r));
    CHECK(!hcsr04_on_edge(&t, GPIO_EDGE_FALLING, 2, &r));
    CHECK(!hcsr04_check_timeout(&t, 100 * MS, &r));
}

static void test_repeated_rise_restarts(void)
{
    hcsr04_tracker t;
    hcsr04_reading r;
    hcsr04_start(&t, 0);
    hcsr04_on_edge(&t, GPIO_EDGE_RISING, 1 * MS, &r);
    CHECK(!hcsr04_on_edge(&t, GPIO_EDGE_RISING, 2 * MS, &r));
    CHECK(hcsr04_on_edge(&t, GPIO_EDGE_FALLING, 3 * MS, &r));
    CHECK(r.width_ns == 1 * MS);
}

static void test_out_of_range(void)
{
    hcsr04_tracker t;
    hcsr04_reading r;
    hcsr04_start(&t, 0);
    hcsr04_on_edge(&t, GPIO_EDGE_RISING, 0, &r);
    CHECK(hcsr04_on_edge(&t, GPIO_EDGE_FALLING, 50 * US, &r)); /* ~0.86 cm */
    CHECK(r.status == HCSR04_OUT_OF_RANGE);

    hcsr04_start(&t, 0);
    hcsr04_on_edge(&t, GPIO_EDGE_RISING, 0, &r);
    CHECK(hcsr04_on_edge(&t, GPIO_EDGE_FALLING, 25 * MS, &r)); /* ~428 cm */
    CHECK(r.status == HCSR04_OUT_OF_RANGE);
}

static void test_timeout_no_rise(void)
{
    hcsr04_tracker t;
    hcsr04_reading r;
    hcsr04_start(&t, 10 * MS);
    CHECK(!hcsr04_check_timeout(&t, 10 * MS + HCSR04_TIMEOUT_NS, &r));
    CHECK(hcsr04_check_timeout(&t, 10 * MS + HCSR04_TIMEOUT_NS + 1, &r));
    CHECK(r.status == HCSR04_TIMEOUT);
    CHECK(r.rise_ns == 0);
    CHECK(t.phase == HCSR04_IDLE);
}

static void test_timeout_stuck_high(void)
{
    hcsr04_tracker t;
    hcsr04_reading r;
    hcsr04_start(&t, 0);
    hcsr04_on_edge(&t, GPIO_EDGE_RISING, 1 * MS, &r);
    CHECK(!hcsr04_check_timeout(&t, 20 * MS, &r));
    CHECK(hcsr04_check_timeout(&t, 1 * MS + HCSR04_TIMEOUT_NS + 1, &r));
    CHECK(r.status == HCSR04_TIMEOUT);
    CHECK(r.rise_ns == 1 * MS);
    /* A late falling edge after timeout must not produce a reading. */
    CHECK(!hcsr04_on_edge(&t, GPIO_EDGE_FALLING, 40 * MS, &r));
}

int main(void)
{
    test_conversion();
    test_valid_echo();
    test_stray_edges_ignored_when_idle();
    test_repeated_rise_restarts();
    test_out_of_range();
    test_timeout_no_rise();
    test_timeout_stuck_high();
    TEST_DONE("test_hcsr04");
}

/* Software-only: PIR motion state machine and debounce. */
#include "../test_util.h"
#include "pir.h"

#define MS 1000000ULL

static void test_no_debounce(void)
{
    pir_state s;
    uint64_t t = 0;
    pir_init(&s, 0, 0);
    CHECK(pir_on_level(&s, 1, 100, &t) == PIR_MOTION_START);
    CHECK(t == 100);
    CHECK(pir_on_level(&s, 1, 200, &t) == PIR_NONE); /* repeated level, e.g. poll sample */
    CHECK(pir_on_level(&s, 0, 300, &t) == PIR_MOTION_END);
    CHECK(t == 300);
    CHECK(!pir_deadline(&s, &t));
}

static void test_debounce_commits_with_edge_time(void)
{
    pir_state s;
    uint64_t t = 0, deadline = 0;
    pir_init(&s, 5 * MS, 0);
    CHECK(pir_on_level(&s, 1, 1 * MS, &t) == PIR_NONE);
    CHECK(pir_deadline(&s, &deadline));
    CHECK(deadline == 6 * MS);
    CHECK(pir_tick(&s, 5 * MS, &t) == PIR_NONE);
    CHECK(pir_tick(&s, 6 * MS, &t) == PIR_MOTION_START);
    CHECK(t == 1 * MS); /* edge time, not commit time */
    CHECK(s.level == 1);
}

static void test_glitch_rejected(void)
{
    pir_state s;
    uint64_t t = 0;
    pir_init(&s, 5 * MS, 0);
    CHECK(pir_on_level(&s, 1, 0, &t) == PIR_NONE);
    CHECK(pir_on_level(&s, 0, 1 * MS, &t) == PIR_NONE);
    CHECK(pir_tick(&s, 20 * MS, &t) == PIR_NONE);
    CHECK(s.level == 0);
    CHECK(!pir_deadline(&s, &t));
}

static void test_stable_change_committed_by_next_edge(void)
{
    /* No tick between edges: the next edge must still commit the stable one. */
    pir_state s;
    uint64_t t = 0;
    pir_init(&s, 5 * MS, 0);
    CHECK(pir_on_level(&s, 1, 0, &t) == PIR_NONE);
    CHECK(pir_on_level(&s, 0, 10 * MS, &t) == PIR_MOTION_START);
    CHECK(t == 0);
    CHECK(pir_tick(&s, 15 * MS, &t) == PIR_MOTION_END);
    CHECK(t == 10 * MS);
}

static void test_initial_level(void)
{
    pir_state s;
    uint64_t t = 0;
    pir_init(&s, 0, 1);
    CHECK(pir_on_level(&s, 1, 0, &t) == PIR_NONE);
    CHECK(pir_on_level(&s, 0, 1, &t) == PIR_MOTION_END);
}

int main(void)
{
    test_no_debounce();
    test_debounce_commits_with_edge_time();
    test_glitch_rejected();
    test_stable_change_committed_by_next_edge();
    test_initial_level();
    TEST_DONE("test_pir");
}

/* Software-only: CSV escaping and record formatting. */
#include "../test_util.h"
#include "csv.h"

#include <string.h>

static void test_escape(void)
{
    char buf[64];
    CHECK(csv_escape_field(buf, sizeof buf, "irq") == 3 && strcmp(buf, "irq") == 0);
    CHECK(csv_escape_field(buf, sizeof buf, "") == 0 && strcmp(buf, "") == 0);
    CHECK(csv_escape_field(buf, sizeof buf, "a,b") > 0 && strcmp(buf, "\"a,b\"") == 0);
    CHECK(csv_escape_field(buf, sizeof buf, "say \"hi\"") > 0 &&
          strcmp(buf, "\"say \"\"hi\"\"\"") == 0);
    CHECK(csv_escape_field(buf, sizeof buf, "x\ny") > 0 && strcmp(buf, "\"x\ny\"") == 0);
    CHECK(csv_escape_field(buf, 4, "abcd") == -1);
    CHECK(csv_escape_field(buf, 4, "abc") == 3);
    CHECK(csv_escape_field(buf, 0, "") == -1);
}

static void test_wall_time(void)
{
    char buf[40];
    struct timespec ts = {.tv_sec = 0, .tv_nsec = 123456789};
    CHECK(csv_format_wall_time(buf, sizeof buf, ts) > 0);
    CHECK(strcmp(buf, "1970-01-01T00:00:00.123456Z") == 0);
    CHECK(csv_format_wall_time(buf, 10, ts) == -1);
}

static void test_records(void)
{
    char buf[256];
    event_record d = {
        .t_mono_ns = 123456789012,
        .t_wall = {.tv_sec = 86400, .tv_nsec = 5000},
        .mode = "irq",
        .kind = EV_DISTANCE,
        .distance_cm = 42.426,
        .echo_ok = 1,
        .latency_ns = 51000,
    };
    CHECK(csv_format_record(buf, sizeof buf, &d) > 0);
    CHECK(strcmp(buf, "123456789012,1970-01-02T00:00:00.000005Z,irq,distance,42.43,1,51000\n") == 0);

    event_record m = {
        .t_mono_ns = 7,
        .t_wall = {0, 0},
        .mode = "poll",
        .kind = EV_MOTION_START,
        .latency_ns = -1,
    };
    CHECK(csv_format_record(buf, sizeof buf, &m) > 0);
    CHECK(strcmp(buf, "7,1970-01-01T00:00:00.000000Z,poll,motion_start,,,\n") == 0);

    CHECK(csv_format_record(buf, 20, &d) == -1);
}

static void test_header_matches_columns(void)
{
    /* 7 columns in the header and in every row */
    size_t commas = 0;
    for (const char *p = CSV_HEADER; *p; p++)
        commas += *p == ',';
    CHECK(commas == 6);
    CHECK(strcmp(csv_event_name(EV_MOTION_END), "motion_end") == 0);
}

int main(void)
{
    test_escape();
    test_wall_time();
    test_records();
    test_header_matches_columns();
    TEST_DONE("test_csv");
}

/* Software-only: latency percentiles, summary, and histogram. */
#include "../test_util.h"
#include "metrics.h"

static void test_summary(void)
{
    int64_t s[100];
    for (int i = 0; i < 100; i++)
        s[i] = 100 - i; /* descending: summarize must sort a copy */
    latency_summary sum;
    CHECK(latency_summarize(s, 100, &sum) == 0);
    CHECK(sum.n == 100);
    CHECK(sum.min == 1 && sum.max == 100);
    CHECK(sum.p50 == 50 && sum.p90 == 90 && sum.p99 == 99);
    CHECK_NEAR(sum.mean, 50.5, 1e-9);
    CHECK(s[0] == 100 && s[99] == 1); /* input untouched */
}

static void test_small_inputs(void)
{
    int64_t one = 42;
    latency_summary sum;
    CHECK(latency_summarize(&one, 1, &sum) == 0);
    CHECK(sum.min == 42 && sum.p50 == 42 && sum.p99 == 42 && sum.max == 42);
    CHECK(latency_summarize(&one, 0, &sum) == -1);

    int64_t sorted[] = {10, 20, 30};
    CHECK(latency_percentile_sorted(sorted, 3, 0) == 10);
    CHECK(latency_percentile_sorted(sorted, 3, 34) == 20);
    CHECK(latency_percentile_sorted(sorted, 3, 100) == 30);
    CHECK(latency_percentile_sorted(sorted, 3, 250) == 30);
}

static void test_histogram(void)
{
    int64_t s[] = {0, 5, 10, 19, 25, 35, 1000, -3};
    uint64_t counts[4] = {99, 99, 99, 99};
    CHECK(latency_histogram(s, 8, 10, counts, 4) == 1);
    CHECK(counts[0] == 2); /* 0, 5 */
    CHECK(counts[1] == 2); /* 10, 19 */
    CHECK(counts[2] == 1); /* 25 */
    CHECK(counts[3] == 2); /* 35 and overflow 1000 */
}

int main(void)
{
    test_summary();
    test_small_inputs();
    test_histogram();
    TEST_DONE("test_metrics");
}

/* Mocked-hardware: scripted edges are delivered in order with their injected
 * timestamps and update line levels, without touching any GPIO. */
#include "../test_util.h"
#include "gpio_mock.h"

int main(void)
{
    gpio_backend *b = gpio_mock_open();
    CHECK(b != NULL);
    if (!b)
        return 1;

    CHECK(b->read(b, PIN_PIR) == 0);
    CHECK(b->write(b, PIN_TRIG, 1) == 0);
    CHECK(b->write(b, PIN_TRIG, 0) == 0);
    CHECK(gpio_mock_write_count(b, PIN_TRIG) == 2);
    CHECK(b->read(b, 1000) == -1);

    gpio_edge e;
    CHECK(b->wait_edge(b, 0, &e) == 0); /* empty queue = timeout */

    CHECK(gpio_mock_push_edge(b, PIN_PIR, GPIO_EDGE_RISING, 1000) == 0);
    CHECK(gpio_mock_push_edge(b, PIN_ECHO, GPIO_EDGE_RISING, 2000) == 0);
    CHECK(gpio_mock_push_edge(b, PIN_ECHO, GPIO_EDGE_FALLING, 3000) == 0);
    CHECK(gpio_mock_push_edge(b, 99, GPIO_EDGE_RISING, 0) == -1);
    CHECK(gpio_mock_pending(b) == 3);

    CHECK(b->wait_edge(b, 0, &e) == 1);
    CHECK(e.pin == PIN_PIR && e.type == GPIO_EDGE_RISING && e.timestamp_ns == 1000);
    CHECK(b->read(b, PIN_PIR) == 1);

    CHECK(b->wait_edge(b, 0, &e) == 1);
    CHECK(e.pin == PIN_ECHO && e.timestamp_ns == 2000);
    CHECK(b->read(b, PIN_ECHO) == 1);

    CHECK(b->wait_edge(b, 0, &e) == 1);
    CHECK(e.type == GPIO_EDGE_FALLING && e.timestamp_ns == 3000);
    CHECK(b->read(b, PIN_ECHO) == 0);

    CHECK(gpio_mock_pending(b) == 0);
    CHECK(b->wait_edge(b, 0, &e) == 0);

    /* Queue grows past its initial capacity. */
    for (uint64_t i = 0; i < 100; i++)
        CHECK(gpio_mock_push_edge(b, PIN_PIR, i % 2 ? GPIO_EDGE_FALLING : GPIO_EDGE_RISING, i) == 0);
    CHECK(gpio_mock_pending(b) == 100);

    CHECK(gpio_mock_set_level(b, PIN_ECHO, 1) == 0);
    CHECK(b->read(b, PIN_ECHO) == 1);

    b->close(b);
    TEST_DONE("test_mock_backend");
}

/* Time source for the pipeline. The real clock uses CLOCK_MONOTONIC (the same
 * clock the kernel uses for GPIO edge timestamps); tests use the mock
 * backend's virtual clock so runs are deterministic. */
#ifndef MONO_CLOCK_H
#define MONO_CLOCK_H

#include <stdint.h>
#include <time.h>

typedef struct {
    uint64_t (*now)(void *ctx);
    /* Sleep until absolute monotonic time t_ns. Returns 0, or EINTR if a
     * signal interrupted the sleep. */
    int (*sleep_until)(void *ctx, uint64_t t_ns);
    /* Wall-clock time, for human-readable timestamps in storage. */
    void (*wall)(void *ctx, struct timespec *ts);
    void *ctx;
} mono_clock;

mono_clock mono_clock_real(void);

#endif

