typedef enum { PIPE_IRQ, PIPE_POLL } pipe_mode;

typedef struct {
    pipe_mode mode;
    uint64_t  poll_interval_ns; /* poll mode: time between samples */
    uint64_t  debounce_ns;      /* PIR stability window; 0 = none */
