/* Time source for the pipeline. The real clock uses CLOCK_MONOTONIC (the same
 * clock the kernel uses for GPIO edge timestamps); tests use the mock
 * backend's virtual clock so runs are deterministic. */
#ifndef MONO_CLOCK_H
#define MONO_CLOCK_H

#include <stdint.h>
#include <time.h>

typedef struct {
    uint64_t (*now)(void *ctx);
    /* Sleep until absolute monotonic time t_ns. Returns 0, or EINTR if a
     * signal interrupted the sleep. */
    int (*sleep_until)(void *ctx, uint64_t t_ns);
    /* Wall-clock time, for human-readable timestamps in storage. */
    void (*wall)(void *ctx, struct timespec *ts);
    void *ctx;
} mono_clock;

mono_clock mono_clock_real(void);

#endif

#include "mono_clock.h"

#include <errno.h>

static uint64_t real_now(void *ctx)
{
    (void)ctx;
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;
}

static int real_sleep_until(void *ctx, uint64_t t_ns)
{
    (void)ctx;
    struct timespec ts = {
        .tv_sec = (time_t)(t_ns / 1000000000ULL),
        .tv_nsec = (long)(t_ns % 1000000000ULL),
    };
    int r = clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, &ts, NULL);
    return r == EINTR ? EINTR : 0;
}

static void real_wall(void *ctx, struct timespec *ts)
{
    (void)ctx;
    clock_gettime(CLOCK_REALTIME, ts);
}

mono_clock mono_clock_real(void)
{
    return (mono_clock){
        .now = real_now,
        .sleep_until = real_sleep_until,
        .wall = real_wall,
        .ctx = NULL,
    };
}

/* Append-only CSV event storage. Each row is written with a single write()
 * and fsync()ed, so a crash or power loss loses at most the row in flight. */
#ifndef CSV_STORE_H
#define CSV_STORE_H

#include "event.h"

typedef struct {
    int fd;
} csv_store;

/* Opens (creating if needed) path for appending. Writes CSV_HEADER if the file
 * is empty. Returns 0, or -1 with errno set. */
int csv_store_open(csv_store *s, const char *path);

/* Returns 0, or -1 on formatting or I/O failure (errno set for I/O). */
int csv_store_append(csv_store *s, const event_record *r);

void csv_store_close(csv_store *s);

#endif

#include "csv_store.h"

#include "csv.h"

#include <errno.h>
#include <fcntl.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

static int write_all(int fd, const char *buf, size_t len)
{
    while (len > 0) {
        ssize_t w = write(fd, buf, len);
        if (w < 0) {
            if (errno == EINTR)
                continue;
            return -1;
        }
        buf += w;
        len -= (size_t)w;
    }
    return 0;
}

int csv_store_open(csv_store *s, const char *path)
{
    s->fd = open(path, O_WRONLY | O_APPEND | O_CREAT | O_CLOEXEC, 0644);
    if (s->fd < 0)
        return -1;

    struct stat st;
    if (fstat(s->fd, &st) < 0 ||
        (st.st_size == 0 && (write_all(s->fd, CSV_HEADER, strlen(CSV_HEADER)) < 0 ||
                             fsync(s->fd) < 0))) {
        int saved = errno;
        close(s->fd);
        s->fd = -1;
        errno = saved;
        return -1;
    }
    return 0;
}

int csv_store_append(csv_store *s, const event_record *r)
{
    char row[256];
    int len = csv_format_record(row, sizeof row, r);
    if (len < 0)
        return -1;
    if (write_all(s->fd, row, (size_t)len) < 0)
        return -1;
    return fsync(s->fd);
}

void csv_store_close(csv_store *s)
{
    if (s->fd >= 0)
        close(s->fd);
    s->fd = -1;
}

