                emit_distance(p, &rd, e.timestamp_ns, handled, true);
        }
        emit_motion(p, pir_tick(&pir, handled, &edge_ns), edge_ns, handled, true);
        if (hcsr04_check_timeout(&rng, handled, &rd))
            emit_distance(p, &rd, handled, handled, false);
    }
