        p->stats->events++;
    } else {
        if (p->stats->store_errors++ == 0)
            perror("csv_store_append");
    }

    if (p->cfg->print_events) {
        char row[256];
        if (csv_format_record(row, sizeof row, &r) > 0)
            fputs(row, stdout);
        fflush(stdout);
    }
}

