     * response that lands after the next stimulus counts as missed. */
    stim_edge s[] = {{100, 1}, {200, 0}, {300, 1}, {400, 0}};
    recv_event e[] = {{150, 1}, {250, 1}, {410, 1}, {450, 0}, {999, 1}};
    int64_t lat[4];
