    CHECK(lat[0] == 50);
    CHECK(lat[1] == -1);
    CHECK(lat[2] == -1); /* the 410 event lies in the next window */
    CHECK(lat[3] == 50);
    CHECK(m.matched == 2 && m.missed == 2);
    CHECK(m.spurious == 3); /* 250 (wrong level), 410 (wrong level), 999 (trailing) */
}

